{
}

Method.Source:
    /// <summary>
    /// MPJ_2677 - Kscerri - 10/06/2021
    /// Updates the 3 fields to the new PO from PR
    /// </summary>
    protected void createLines()
    {
        PurchReqTable   intPurchreqTable;
        PurchParameters purchParameters;

        next createLines();

        intPurchreqTable = PurchReqTable::findByPurchReqId(purchLine.purchReqId);
        purchParameters  = PurchParameters::find();

        if (intPurchreqTable.BusinessJustification == purchParameters.METPRReason)
        {
            purchTable.selectForUpdate(true);
            purchTable.ReasonTableRef = ReasonTableRef::createFromCode(purchParameters.METPOReason);
            purchTable.METCustAcc     = intPurchreqTable.METCustAcc;
            purchTable.METCustName    = intPurchreqTable.METCustName;
            purchTable.update();
        }
    }
